-- Migration to block disposable/temporary email domains
CREATE TABLE IF NOT EXISTS public.blocked_email_domains (
  domain TEXT PRIMARY KEY,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Enable RLS
ALTER TABLE public.blocked_email_domains ENABLE ROW LEVEL SECURITY;

-- Read access policy
DROP POLICY IF EXISTS "Allow public read access to blocked_email_domains" ON public.blocked_email_domains;
CREATE POLICY "Allow public read access to blocked_email_domains" 
ON public.blocked_email_domains FOR SELECT 
USING (true);

-- Manage access policy (admins/owners)
DROP POLICY IF EXISTS "Allow admin to manage blocked_email_domains" ON public.blocked_email_domains;
CREATE POLICY "Allow admin to manage blocked_email_domains"
ON public.blocked_email_domains FOR ALL
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.profiles
    WHERE profiles.user_id = auth.uid()
    AND (profiles.role = 'admin' OR profiles.role = 'owner')
  )
);

